        const ev = parseFloat(r.launch_speed); if(!isNaN(ev)){s.launch_speeds.push(ev);if(ev>=95)s.hard_hits++;if(side){side.launch_speeds.push(ev);if(ev>=95)side.hard_hits++;}}
